    /* =================== small helpers =================== */
  
    function esc(s) {
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }
    function isoToday() {
      var d = new Date();
      return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate());
    }
    function p2(n) { n = String(n); return n.length < 2 ? '0' + n : n; }
  
    /** "2026-10-11" -> a Date at noon, so time zones can never shift the day. */
    function toDate(iso) {
      var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
      if (!m) return null;
      return new Date(+m[1], +m[2] - 1, +m[3], 12, 0, 0);
    }
    function daysBetween(aIso, bIso) {
      var a = toDate(aIso), b = toDate(bIso);
      if (!a || !b) return null;
      return Math.round((b - a) / 86400000);
    }
    function fmtDay(iso) {
      var d = toDate(iso);
      if (!d) return '';
      return d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
    }
    function fmtShort(iso) {
      var d = toDate(iso);
      if (!d) return '';
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    }
    function fmtLong(iso) {
      var d = toDate(iso);
      if (!d) return '';
      return d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
    }
    /** "Tomorrow", "In 3 days", "2 days ago" */
    function relative(n) {
      if (n === null) return '';
      if (n === 0) return 'Today';
      if (n === 1) return 'Tomorrow';
      if (n === -1) return 'Yesterday';
      if (n < 0) {
        var ago = -n;
        if (ago < 7) return ago + ' days ago';
        var w = Math.round(ago / 7);
        return w === 1 ? '1 week ago' : w + ' weeks ago';
      }
      if (n < 7) return 'In ' + n + ' days';
      var wk = Math.round(n / 7);
      return wk === 1 ? 'In 1 week' : 'In ' + wk + ' weeks';
    }
    function linkFor(text, url) {
      if (!text) return '';
      if (!url) return '<span>' + esc(text) + '</span>';
      return '<a href="' + esc(url) + '">' + esc(text) + '</a>';
    }
    function slug(s) {
      return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    }
