    /* ============================================================
       Below here is the machinery. You should not need to edit it.
       ============================================================ */
  
    var KINDS = { music: "Music", justice: "Justice", holiday: "Holiday", station: "Station" };
    var MN = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    var DN = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
    var LOOKAHEAD = 190;  // days ahead to show. 190 carries past the 50th.
    var LOOKBACK  = 2;    // days just past to keep visible
  
