      var a = MN[s.getMonth()].slice(0, 3) + " " + s.getDate();
      if (e.getTime() !== s.getTime()) return a + " to " + MN[e.getMonth()].slice(0, 3) + " " + e.getDate();
      return DN[s.getDay()].slice(0, 3) + ", " + a;
