    var DOMAIN = /((?:[a-z0-9][a-z0-9-]*\.)+(?:com|org|net|io|news|fm|tv|co|us|land|dev|me|gov|info|xyz|edu|cc|uk|ca|za|ie|au|nz|de|fr)(?:\/[A-Za-z0-9._~:\/?#@!$&'()*+,;=%-]*)?)/i;
  
